function readSettings(){
  try{const saved=Number(localStorage.getItem('pinball-volume'));return {sound:localStorage.getItem('pinball-sound')!=='off',volume:localStorage.getItem('pinball-volume')===null?1:Math.max(0,Math.min(1,Number.isFinite(saved)?saved:1)),launchMode:localStorage.getItem('pinball-launch-mode')==='drag'?'drag':'hold'};}
  catch{return {sound:true,volume:1,launchMode:'hold'};}
}
function showVolume(){volumeValue.textContent=volumeInput.value+'%';}
function openSettings(){
  if(settingsOpen)return;
  settingsOpen=true;menuAnimation?.pause();syncMenuMusic();previousFocus=document.activeElement;current?.suspend();
  const values=readSettings();soundInput.checked=values.sound;volumeInput.value=Math.round(values.volume*100);showVolume();launchInput.value=values.launchMode;
  screen.inert=true;menu.inert=true;settingsButton.hidden=true;settingsPage.hidden=false;
  document.getElementById('save-status').textContent='';document.getElementById('close-settings').focus();
}
function closeSettings(){
  if(!settingsOpen||document.hidden)return;
  settingsOpen=false;settingsPage.hidden=true;screen.inert=false;menu.inert=false;
  settingsButton.hidden=!!current?.api?.game;settingsPosition();drawMenu();current?.resume();menuAnimation?.resume();syncMenuMusic();
  if(previousFocus?.isConnected)previousFocus.focus();
}
function saveSettings(){
  const values={sound:soundInput.checked,volume:Number(volumeInput.value)/100,launchMode:launchInput.value};showVolume();
  current?.setSettings(values);syncMenuMusic(values.sound,values.volume);
  try{localStorage.setItem('pinball-sound',values.sound?'on':'off');localStorage.setItem('pinball-volume',String(values.volume));localStorage.setItem('pinball-launch-mode',values.launchMode);document.getElementById('save-status').textContent='';}
  catch{document.getElementById('save-status').textContent='無法保存';}
}
document.getElementById('clear-game-records').onclick=()=>{if(!confirm('確定清除排行榜、關卡進度及劇情已讀紀錄？目前遊戲將結束，音效與操作設定會保留。'))return;
  try{const keys=Object.keys(localStorage).filter(key=>key==='pinball-high-scores-v1'||key==='pinball-pirate-progress-v1'||key.startsWith('pinball-pirate-story-seen-v1:'));for(const key of keys)localStorage.removeItem(key);location.href=new URL('main.html',location.href).href;}
  catch{document.getElementById('save-status').textContent='清除失敗，請再試一次。';}
};
settingsButton.onclick=openSettings;document.getElementById('close-settings').onclick=closeSettings;
soundInput.onchange=saveSettings;volumeInput.oninput=saveSettings;launchInput.onchange=saveSettings;
document.addEventListener('visibilitychange',()=>{if(document.hidden)openSettings();});
window.addEventListener('pagehide',openSettings);
window.addEventListener('pageshow',()=>syncMenuMusic());

async function show(url){
  const id=++revision;current?.dispose();error.hidden=true;menu.hidden=true;screen.hidden=false;syncMenuMusic();
  const next=createView(screen,url,{onSettings:openSettings,onExit:()=>{if(current)leaveBossStage(current);},appSettings:readSettings()});current=next;settingsPosition();if(settingsOpen)next.suspend();
  try{await next.ready;if(id===revision){const body=next.shadow.getElementById('view-body');body.tabIndex=-1;settingsButton.hidden=settingsOpen||transitioning||!!next.api?.game;if(!settingsOpen&&!transitioning)body.focus();return next;}}
  catch(e){if(id===revision&&e.name!=='AbortError'){error.textContent=e.message;error.hidden=false;}return null;}
}
async function fadeSceneBlack(opacity){
 sceneTransition.hidden=false;
 const from=Number(sceneTransition.style.opacity||0);
 const animation=sceneTransition.animate([{opacity:from},{opacity}],{duration:450,easing:'ease-in-out',fill:'forwards'});
 await animation.finished;
 sceneTransition.style.opacity=String(opacity);animation.cancel();
 if(opacity===0)sceneTransition.hidden=true;
}
async function playBossStory(stage,part){
 const story=await show(new URL(`story/pirate-chapter${stage}-${part}.html?embed=1`,mainPageURL));
 if(!story)throw Error(`無法載入第 ${stage} 關${part==='start'?'開場':'結尾'}`);
 await Promise.all([...story.shadow.querySelectorAll('#phone img')].map(image=>image.decode()));
 for(const id of ['begin','replay','credits'])story.shadow.getElementById(id).hidden=true;
 const completed=new Promise(resolve=>story.events.addEventListener('story:complete',resolve,{once:true}));
 screen.inert=false;
 try{
  await fadeSceneBlack(0);
  // WebViews may require a fresh tap for newly created audio elements.
  // Keep the completion listener alive while the story's Play button retries.
  if(await story.api.play(`ch${stage}-${part}`)!==true)story.shadow.getElementById('begin').hidden=false;
  await completed;
 }finally{screen.inert=true;}
}
function saveBossProgress(){
 try{localStorage.setItem('pinball-pirate-progress-v1',JSON.stringify(bossProgress));}catch{error.textContent='關卡進度無法保存';error.hidden=false;}
}
function animateBossUnlock(stage){
 if(stage!=='endless'&&stage>8)return Promise.resolve();
 menuUnlockAnimation={stage,lockFade:0,bossReveal:0,shake:0};
 return new Promise(resolve=>{
  const started=performance.now();
  function frame(now){
   const elapsed=now-started;
   menuUnlockAnimation.shake=elapsed<650?Math.sin(elapsed/36)*Math.sin(Math.PI*Math.min(1,elapsed/650))*5:0;
   menuUnlockAnimation.lockFade=Math.max(0,Math.min(1,(elapsed-650)/600));
   menuUnlockAnimation.bossReveal=Math.max(0,Math.min(1,(elapsed-1250)/600));
   drawMenu();
   if(elapsed<1850)requestAnimationFrame(frame);else{menuUnlockAnimation=null;resolve();}
  }
  requestAnimationFrame(frame);
 });
}
